// Items for a workshop run (pure): each planned skill at the tier of its Leitner box, generated by
// src/measurement. The fence and tiling rounds share one rectangle (chu vi then diện tích of the
// same floor), and a tier-1 tiling floor stays small enough to cover by taps. Both are found by
// drawing items from the run's rng until one fits (bounded; the odds are about 1 in 160).
import type { GeoItem } from '../../geometry/geo-scene-types';
import { type FactKey, skillKey } from '../../learning/fact-key';
import type { FactStat } from '../../learning/learning-types';
import type { Rng } from '../../learning/seeded-rng';
import { type SkillTier, skillTierOf } from '../../learning/skill-tiers';
import { measurementItemForSkill } from '../../measurement/measurement-item-for-skill';
import { STATION_OF, type WorkshopStation } from './workshop-stations';
import { tileTargets } from './workshop-tile-grid';

export interface WorkshopRound {
  readonly skillId: string;
  readonly factKey: FactKey;
  readonly tier: SkillTier;
  readonly station: WorkshopStation;
  readonly item: GeoItem;
  /** The shape is covered tile by tile (else solved by the formula or by reading). */
  readonly tiling: boolean;
}

const MAX_DRAWS = 4000;

/** [width, height] of a rectangle scene, else null. */
export function rectOf(item: GeoItem | undefined): [number, number] | null {
  const s = item?.scene;
  return s?.kind === 'rect' ? [s.width, s.height] : null;
}

function draw(id: string, rng: Rng, tier: SkillTier, fits: (item: GeoItem) => boolean): GeoItem {
  let item = measurementItemForSkill(id, rng, tier);
  for (let i = 1; i < MAX_DRAWS && !fits(item); i++) item = measurementItemForSkill(id, rng, tier);
  return item;
}

export function planWorkshopRounds(
  skills: readonly string[],
  stats: Readonly<Record<string, FactStat | undefined>>,
  rng: Rng,
): WorkshopRound[] {
  const tierOf = (id: string) => skillTierOf(stats[skillKey(id)]);
  // The floor to tile comes first, so the fence round can be drawn around the same rectangle.
  const areaTier = tierOf('meas-area-rect');
  const floor = skills.includes('meas-area-rect')
    ? draw('meas-area-rect', rng, areaTier, (it) => areaTier !== 1 || !!tileTargets(it.scene, 1))
    : null;
  const same = rectOf(floor ?? undefined);
  return skills.map((skillId) => {
    const tier = tierOf(skillId);
    let item: GeoItem;
    if (skillId === 'meas-area-rect' && floor) item = floor;
    else if (skillId === 'meas-perimeter-rect' && same) {
      item = draw(skillId, rng, tier, (it) => {
        const r = rectOf(it);
        return !!r && r[0] === same[0] && r[1] === same[1];
      });
    } else item = measurementItemForSkill(skillId, rng, tier);
    return {
      skillId,
      factKey: skillKey(skillId),
      tier,
      station: STATION_OF[skillId] as WorkshopStation,
      item,
      tiling: tileTargets(item.scene, tier) !== null,
    };
  });
}
